export default function recipients({ from, to }) {
  if (typeof from !== "string" || typeof to !== "string" || !from.trim() || !to.trim())
    throw Error("Sender and recipient are required");
  return { from: { email: from.trim() }, to: [{ email: to.trim() }] };
}

