export default function rows({ body }) {
  if (typeof body !== "string") throw Error("Missing Hacker News HTML");
  const decode = (s) =>
    s.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (v, k) => {
      if (k[0] === "#") {
        let n = k[1].toLowerCase() === "x" ? parseInt(k.slice(2), 16) : parseInt(k.slice(1), 10);
        return Number.isFinite(n) && n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : v;
      }
      return { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" }[k.toLowerCase()] ?? v;
    });
  const matches = [
    ...body.matchAll(
      /<span\s+class="titleline"[^>]*>\s*<a\s+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi,
    ),
  ];
  if (!matches.length) throw Error("No Hacker News front-page stories found");
  let records = matches.map((m) => {
    let title = decode(m[2].replace(/<[^>]*>/g, "")),
      url = decode(m[1]);
    if (!title.trim() || !url.trim()) throw Error("Invalid story");
    return [title, url];
  });
  return {
    worksheetData: { "Latest news": [["news_title", "news_url"], ...records] },
    path: "hn-news-" + Date.now() + ".xlsx",
  };
}

