import { Buffer } from "node:buffer";
export default async function attachment({ content }, context) {
  let url = content?.s3url;
  if (typeof url !== "string" || !url.startsWith("https://")) throw Error("Missing transit URL");
  let r = await context.fetch(url, { method: "GET" });
  if (!r.ok) throw Error("Workbook download failed");
  let b = Buffer.from(await r.arrayBuffer());
  if (b.length < 4 || b[0] !== 0x50 || b[1] !== 0x4b || b[2] !== 3 || b[3] !== 4)
    throw Error("Workbook is not an XLSX ZIP");
  return {
    attachments: [
      {
        contentBase64: b.toString("base64"),
        filename: "Ycombinator_news.xlsx",
        type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        disposition: "attachment",
      },
    ],
  };
}
